const express = require('express');
const { PrismaClient } = require('@prisma/client');

const prisma = new PrismaClient();
const app = express();

function getTenantPrisma(tenantId) {
  return prisma.$extends({
    query: {
      customer: {
        async $allOperations({ model, operation, args, query }) {
          args.where = { ...args.where, tenantId };
          return query(args);
        }
      },
      paymentMethod: {
        // Enforce tenant boundary on child relational model as well
        async $allOperations({ model, operation, args, query }) {
          args.where = { ...args.where, tenantId };
          return query(args);
        }
      }
    }
  });
}

app.get('/api/customers/:customerId/vault', async (req, res) => {
  if (!req.user || !req.user.tenantId) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  const tenantPrisma = getTenantPrisma(req.user.tenantId);

  const customer = await tenantPrisma.customer.findFirst({
    where: {
      id: req.params.customerId,
      tenantId: req.user.tenantId
    },
    include: {
      paymentMethods: {
        where: { tenantId: req.user.tenantId }
      }
    }
  });

  if (!customer) {
    return res.status(404).json({ error: 'Customer not found' });
  }

  res.json({ customer });
});

app.listen(8088);
